/* phase index n(v) of each task (order of TASKS) */
static const uint8_t TASK_PHASE[N_TASKS] = {0, 0, 0, 1, 2, 2, 3, 4, 1, 2, 3, 3, 4, 4, 5, 6, 7, 8, 9, 9, 10, 11, 11};
